async (transaction) => {
            const userRef = firestore().doc(`${OSKUserController.collection}/${userId}`);
            const userDoc = await transaction.get(userRef);
            if (!userDoc.exists) return 1;

            const currentCount = userDoc.data()?.unreadNotificationCount || 0;
            const updatedCount = currentCount + 1;
            transaction.update(userRef, { unreadNotificationCount: updatedCount });
            return updatedCount;
        }

async (transaction) => {
            const userRef = firestore().doc(`${OSKUserController.collection}/${userId}`);
            const userDoc = await transaction.get(userRef);
            if (userDoc.exists) {
                const currentCount = userDoc.data()?.unreadNotificationCount || 0;
                const newCount = Math.max(0, currentCount - 1);
                transaction.update(userRef, { unreadNotificationCount: newCount });
            }
        }

invitees.map(async (invitee) => {
                // Initialize a flag to determine if the invitee matches the invited user
                let isMatchingInvitee = false;

                // Check the type of inviteeContactInfo and set the flag accordingly
                switch (invitee.inviteeContactInfo.invitationType) {
                    case 'mail':
                        if (invitee.inviteeContactInfo.email === invitedUser.email) {
                            isMatchingInvitee = true;
                        }
                        break;
                    case 'phone':
                        if (
                            invitee.inviteeContactInfo.phoneNumber.localPhoneNumber ===
                            invitedUser.phoneNumber?.localPhoneNumber
                        ) {
                            isMatchingInvitee = true;
                        }
                        break;
                    case 'user':
                        if (invitee.inviteeContactInfo.inviteeId === invitedUser.userId) {
                            isMatchingInvitee = true;
                        }
                        break;
                    default:
                        break;
                }

                if (options.status === 'accepted' && !options.accessId) {
                    OSKUserInvitationCommonService.logger.logError(
                        `No access id found for accepted invitation with id ${invitationId}`,
                        { invitationId }
                    );
                    throw new Error(`No access id found for accepted invitation with id ${invitationId}`);
                }

                // Proceed with the update only if the invitee matches
                if (isMatchingInvitee) {
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    const updatePayload = { status: options.status } as any;

                    // Add accessId to the payload if it's provided and relevant
                    if ((options.status === 'accepted' || options.status === 'cancelled') && options.accessId) {
                        updatePayload.accessId = options.accessId;
                    }

                    await OSKUserInvitationController.default.update(invitedUser.userId, invitationId, updatePayload);

                    // Construct the updated invitee object
                    const updatedInvitee = { ...invitee, status: options.status };
                    // Include accessId in the updated invitee if relevant
                    if ((options.status === 'accepted' || options.status === 'cancelled') && options.accessId) {
                        updatedInvitee.accessId = options.accessId;
                    }
                    return updatedInvitee;
                } else {
                    // Return the original invitee if there's no match
                    return invitee;
                }
            })

