                if (externalUserInvitationDoc.unitInvitations) {
                    const unitsOnboarded = await OSKUserInvitationExternalUserService.processUnitInvitations(
                        user,
                        externalUserInvitationDoc.unitInvitations
                    );
                    if (unitsOnboarded) {
                        unitInvitations.push(...unitsOnboarded);
                    }
                }
                if (externalUserInvitationDoc.userInvitations) {
                    const userInvitations = await OSKUserInvitationExternalUserService.processUserInvitations(
                        user.userId,
                        externalUserInvitationDoc.userInvitations
                    );
                    if (userInvitations) {
                        guestInvitations.push(...userInvitations);
                    }
                }

                // --- DELETION LOGIC ---
                // The document has been fully processed, we can now delete it to prevent re-processing.
                await OSKUserInvitationExternalUserController.default.delete(externalUserInvitationDoc.id);
                OSKUserInvitationExternalUserService.logger.logInfo(
                    `Successfully processed and deleted externalUserInvitation: ${externalUserInvitationDoc.id}`
                );
            } catch (error) {
                OSKUserInvitationExternalUserService.logger.logError(
                    `Failed to process externalUserInvitation: ${externalUserInvitationDoc.id}. It will not be deleted.`,
                    { error, docId: externalUserInvitationDoc.id }
                );
            }
        }

